-- Disposable ONLY; every identity, header-free digest and credential placeholder is synthetic.
begin;
create function pg_temp.expect(ok boolean,label text) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'CALENDAR 5B TEST: %',label;end if;end$$;
create function pg_temp.denied(q text) returns boolean language plpgsql as $$begin execute q;return false;exception when insufficient_privilege or unique_violation then return true;end$$;
insert into public.app_members(email,is_active) values('calendar.one@synthetic.test',true),('calendar.two@synthetic.test',true),('calendar.noperm@synthetic.test',true),('calendar.inactive@synthetic.test',false);
insert into public.member_permissions(email,permission) values('calendar.one@synthetic.test','calendar_completion'),('calendar.two@synthetic.test','calendar_completion');
insert into public.google_mailbox_connections(email,granted_scopes,refresh_token_encrypted,refresh_token_iv,refresh_token_tag)
 select email,array['https://www.googleapis.com/auth/calendar.events','https://www.googleapis.com/auth/calendar.readonly'],'synthetic-cipher','synthetic-iv','synthetic-tag' from public.app_members where email in ('calendar.one@synthetic.test','calendar.two@synthetic.test');
create temp table calendar_ctx(v jsonb);grant all on calendar_ctx to authenticated;
set local role anon;
select pg_temp.expect(pg_temp.denied($q$select public.calendar_completion_context()$q$),'anon denied');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","email":"calendar.stranger@synthetic.test"}',true);
select pg_temp.expect(pg_temp.denied($q$select public.calendar_completion_state()$q$),'nonmember denied');
select set_config('request.jwt.claims','{"role":"authenticated","email":"calendar.inactive@synthetic.test"}',true);
select pg_temp.expect(pg_temp.denied($q$select public.list_calendar_reviews()$q$),'inactive denied');
select set_config('request.jwt.claims','{"role":"authenticated","email":"calendar.one@synthetic.test"}',true);
select pg_temp.expect(not public.calendar_completion_state(),'off by default');
select pg_temp.expect(pg_temp.denied($q$select public.calendar_completion_context()$q$),'flag blocks dispatch');
reset role;
update private.calendar_completion_configuration set enabled=true;
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","email":"calendar.noperm@synthetic.test"}',true);
select pg_temp.expect(not public.calendar_completion_state(),'canonical permission absent');
select pg_temp.expect(pg_temp.denied($q$select public.calendar_completion_context()$q$),'permissionless denied');
select set_config('request.jwt.claims','{"role":"authenticated","email":"calendar.one@synthetic.test"}',true);
insert into calendar_ctx select public.calendar_completion_context();
select public.create_calendar_review('f6000000-0000-0000-0000-000000000001','save',repeat('a',64),(select v->>'connectionRevision' from calendar_ctx),repeat('c',64));
select pg_temp.expect(public.create_calendar_review('f6000000-0000-0000-0000-000000000001','save',repeat('a',64),(select v->>'connectionRevision' from calendar_ctx),repeat('c',64))='f6000000-0000-0000-0000-000000000001','create idempotent');
select pg_temp.expect(pg_temp.denied($q$select public.advance_calendar_review('f6000000-0000-0000-0000-000000000001','completed')$q$),'cannot skip claim');
select pg_temp.expect(pg_temp.denied($q$select public.advance_calendar_review('f6000000-0000-0000-0000-000000000001','claim',repeat('b',64))$q$),'stale content denied');
select pg_temp.expect(public.advance_calendar_review('f6000000-0000-0000-0000-000000000001','claim',repeat('a',64))='claimed','claim');
select pg_temp.expect(pg_temp.denied($q$select public.advance_calendar_review('f6000000-0000-0000-0000-000000000001','claim',repeat('a',64))$q$),'claim never reissued');
select pg_temp.expect(public.advance_calendar_review('f6000000-0000-0000-0000-000000000001','cancel')='cancelled','cancel mid-roundtrip before dispatch');
select pg_temp.expect(pg_temp.denied($q$select public.advance_calendar_review('f6000000-0000-0000-0000-000000000001','dispatch',repeat('a',64))$q$),'cancel wins dispatch fence');
select public.create_calendar_review('f6000000-0000-0000-0000-000000000002','save',repeat('a',64),(select v->>'connectionRevision' from calendar_ctx),repeat('c',64));
select public.advance_calendar_review('f6000000-0000-0000-0000-000000000002','claim',repeat('a',64));
select public.advance_calendar_review('f6000000-0000-0000-0000-000000000002','dispatch',repeat('a',64));
select pg_temp.expect(public.advance_calendar_review('f6000000-0000-0000-0000-000000000002','cancel')='uncertain','late cancel never claims no delivery');
select pg_temp.expect(pg_temp.denied($q$select public.advance_calendar_review('f6000000-0000-0000-0000-000000000002','claim',repeat('a',64))$q$),'uncertain cannot retry');
select pg_temp.expect(pg_temp.denied($q$select public.create_calendar_review('f6000000-0000-0000-0000-000000000003','save',repeat('b',64),(select v->>'connectionRevision' from calendar_ctx),repeat('c',64))$q$),'uncertain resource cannot obtain another review');
select set_config('request.jwt.claims','{"role":"authenticated","email":"calendar.two@synthetic.test"}',true);
select pg_temp.expect((select count(*)=0 from public.list_calendar_reviews()),'owner isolation');
select pg_temp.expect(pg_temp.denied($q$select public.advance_calendar_review('f6000000-0000-0000-0000-000000000002','cancel')$q$),'cannot cancel another owner');
select set_config('request.jwt.claims','{"role":"authenticated","email":"calendar.one@synthetic.test"}',true);
select public.create_calendar_review('f6000000-0000-0000-0000-000000000004','save',repeat('a',64),(select v->>'connectionRevision' from calendar_ctx),repeat('d',64));
select public.advance_calendar_review('f6000000-0000-0000-0000-000000000004','claim',repeat('a',64));
reset role;
-- Same transaction/updated_at: epoch includes cipher/scopes, not timestamp alone.
update public.google_mailbox_connections set refresh_token_encrypted='synthetic-rotated',granted_scopes=array['https://www.googleapis.com/auth/calendar.readonly'] where email='calendar.one@synthetic.test';
set local role authenticated;
select pg_temp.expect(pg_temp.denied($q$select public.advance_calendar_review('f6000000-0000-0000-0000-000000000004','dispatch',repeat('a',64))$q$),'scope revocation fences write');
reset role;
update public.google_mailbox_connections set granted_scopes=array['https://www.googleapis.com/auth/calendar.events'] where email='calendar.one@synthetic.test';
set local role authenticated;
select pg_temp.expect(pg_temp.denied($q$select public.advance_calendar_review('f6000000-0000-0000-0000-000000000004','dispatch',repeat('a',64))$q$),'reconnect invalidates previous review');
reset role;
-- DELETE: disposable synthetic connection only, simulating disconnect.
delete from public.google_mailbox_connections where email='calendar.one@synthetic.test';
set local role authenticated;
select pg_temp.expect(pg_temp.denied($q$select public.calendar_completion_context()$q$),'connection revoked');
select pg_temp.expect(public.advance_calendar_review('f6000000-0000-0000-0000-000000000004','cancel')='cancelled','can cancel own pre-dispatch review after disconnect');
reset role;
insert into auth.users(id,email) values('f6000000-0000-0000-0000-000000000099','calendar.service@synthetic.test');
insert into private.machine_identities(sub,enabled,relationships_only) values('f6000000-0000-0000-0000-000000000099',true,true);
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"f6000000-0000-0000-0000-000000000099","email":"calendar.service@synthetic.test"}',true);
select pg_temp.expect(pg_temp.denied($q$select public.calendar_completion_state()$q$),'machine state denied');
select pg_temp.expect(pg_temp.denied($q$select public.calendar_completion_context()$q$),'machine context denied');
select pg_temp.expect(pg_temp.denied($q$select public.list_calendar_reviews()$q$),'machine reviews denied');
select pg_temp.expect(pg_temp.denied($q$select * from private.calendar_mutation_reviews$q$),'no direct table read');
select pg_temp.expect(pg_temp.denied($q$insert into private.calendar_completion_configuration values(false,true)$q$),'no direct config writes');
reset role;
insert into public.google_mailbox_connections(email,granted_scopes,refresh_token_encrypted,refresh_token_iv,refresh_token_tag) values('calendar.one@synthetic.test',array['https://www.googleapis.com/auth/calendar.events'],'synthetic','synthetic','synthetic');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","email":"calendar.one@synthetic.test"}',true);
reset role;
select pg_temp.expect(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('calendar_completion_context','calendar_completion_state','create_calendar_review','advance_calendar_review','list_calendar_reviews') and p.prosecdef),'public RPCs invoker');
select pg_temp.expect((select count(*)=3 from pg_policy where polname='machine_identity_isolation' and polrelid in('private.calendar_completion_configuration'::regclass,'private.calendar_completion_baseline'::regclass,'private.calendar_mutation_reviews'::regclass) and pg_get_expr(polqual,polrelid) like '%SELECT%' and pg_get_expr(polwithcheck,polrelid) like '%SELECT%'),'all new tables isolated via InitPlan');
select pg_temp.expect(not exists(select 1 from information_schema.columns where table_schema='private' and table_name in ('calendar_mutation_reviews') and column_name in ('body','html','mime','payload','recipients','alias','subject','resumable_url')),'no content or resumable URL store');
-- Definitive provider rejection closes only this review, allowing a NEW confirmation.
set local role authenticated;
select public.create_calendar_review('f6000000-0000-0000-0000-000000000020','save',repeat('a',64),public.calendar_completion_context()->>'connectionRevision',repeat('f',64));
select public.advance_calendar_review('f6000000-0000-0000-0000-000000000020','claim',repeat('a',64));
select public.advance_calendar_review('f6000000-0000-0000-0000-000000000020','dispatch',repeat('a',64));
select pg_temp.expect(public.advance_calendar_review('f6000000-0000-0000-0000-000000000020','rejected')='cancelled','definitive refusal releases resource');
select public.create_calendar_review('f6000000-0000-0000-0000-000000000021','save',repeat('b',64),public.calendar_completion_context()->>'connectionRevision',repeat('f',64));
select public.advance_calendar_review('f6000000-0000-0000-0000-000000000021','cancel');
select pg_temp.expect(pg_temp.denied($q$select public.advance_calendar_review('f6000000-0000-0000-0000-000000000002','rejected')$q$),'uncertain cannot be relabelled rejected');
reset role;
do $$declare p text;c text;begin select pg_get_constraintdef(oid) into c from pg_constraint where conrelid='public.member_permissions'::regclass and conname='member_permissions_permission_check';foreach p in array array['admin','portfolio','documents','email_scouting','lp_scouting','relationship_intelligence','mail_completion','calendar_completion'] loop if position(quote_literal(p) in c)=0 then raise exception 'Lost permission %',p;end if;end loop;end$$;
-- Permission and active membership are rechecked at the last dispatch fence.
set local role authenticated;
select public.create_calendar_review('f6000000-0000-0000-0000-000000000030','save',repeat('a',64),public.calendar_completion_context()->>'connectionRevision',repeat('e',64));
reset role;
-- DELETE: synthetic permission only, simulating revocation.
delete from public.member_permissions where email='calendar.one@synthetic.test' and permission='calendar_completion';
set local role authenticated;
select pg_temp.expect(pg_temp.denied($q$select public.advance_calendar_review('f6000000-0000-0000-0000-000000000030','claim',repeat('a',64))$q$),'revoked permission blocks claim');
reset role;
insert into public.member_permissions values('calendar.one@synthetic.test','calendar_completion');
update public.app_members set is_active=false where email='calendar.one@synthetic.test';
set local role authenticated;
select pg_temp.expect(pg_temp.denied($q$select public.advance_calendar_review('f6000000-0000-0000-0000-000000000030','claim',repeat('a',64))$q$),'deactivated member blocks claim');
reset role;
update public.app_members set is_active=true where email='calendar.one@synthetic.test';
set local role authenticated;
select public.advance_calendar_review('f6000000-0000-0000-0000-000000000030','cancel');
reset role;
-- Task view: own assignments only; restricted parents and hidden companies remain hidden.
insert into public.companies(id,name) values('f6000000-0000-0000-0000-000000000060','Synthetic calendar company');
insert into public.deals(id,company_id,name,stage_id,restricted) values('f6000000-0000-0000-0000-000000000061','f6000000-0000-0000-0000-000000000060','Synthetic restricted calendar Deal',(select id from public.pipeline_stages order by id limit 1),true);
insert into public.tasks(id,title,assignee_email,due_at) values('f6000000-0000-0000-0000-000000000062','Synthetic own task','calendar.one@synthetic.test','2026-10-16'),('f6000000-0000-0000-0000-000000000063','Synthetic other task','calendar.two@synthetic.test','2026-10-16');
insert into public.tasks(id,title,assignee_email,due_at,company_id,deal_id) values('f6000000-0000-0000-0000-000000000064','Synthetic restricted task','calendar.one@synthetic.test','2026-10-16','f6000000-0000-0000-0000-000000000060','f6000000-0000-0000-0000-000000000061');
set local role authenticated;
select pg_temp.expect((select count(*)=1 from public.calendar_task_overlay('2026-10-01','2026-11-01')),'task owner isolation and restricted Deal');
reset role;
insert into public.tasks(id,title,assignee_email,due_at,company_id) values('f6000000-0000-0000-0000-000000000065','Synthetic hidden company task','calendar.one@synthetic.test','2026-10-16','f6000000-0000-0000-0000-000000000060');
create policy calendar_test_hidden_company on public.companies as restrictive for select to authenticated using(id<>'f6000000-0000-0000-0000-000000000060');
set local role authenticated;
select pg_temp.expect((select count(*)=1 from public.calendar_task_overlay('2026-10-01','2026-11-01')),'hidden company not revealed');
reset role;
-- Synthetic backlog: expiry work is bounded too, not only the returned history.
insert into private.calendar_mutation_reviews(id,owner_email,operation,revision,connection_revision,resource_hash,state,created_at,expires_at,dispatch_started_at)
select md5('synthetic-expired-'||n)::uuid,'calendar.one@synthetic.test','save',repeat('a',64),'synthetic',md5('resource'||n)||md5('resource2'||n),'claimed',now()-interval '20 minutes',now()-interval '11 minutes',now()-interval '19 minutes' from generate_series(1,125)n;
set local role authenticated;
select pg_temp.expect((select count(*)=25 from public.list_calendar_reviews()),'history response bounded');
reset role;
select pg_temp.expect((select count(*)=25 from private.calendar_mutation_reviews where owner_email='calendar.one@synthetic.test' and state='claimed'),'expiry updates at most 100 per call');
set local role authenticated;
select count(*) from public.list_calendar_reviews();
reset role;
select pg_temp.expect(not exists(select 1 from private.calendar_mutation_reviews where owner_email='calendar.one@synthetic.test' and state='claimed'),'expired claims become uncertain, never reclaimed');
rollback;
